use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};
use std::io::{self, Read, Write};

#[derive(Default)]
struct Graph {
    ids: HashMap<String, usize>,
    names: Vec<String>,
    out: Vec<HashMap<usize, u64>>,
    inn: Vec<HashMap<usize, u64>>,
}

impl Graph {
    fn node(&mut self, s: &str) -> usize {
        if let Some(&i) = self.ids.get(s) {
            return i;
        }
        let i = self.names.len();
        self.ids.insert(s.to_string(), i);
        self.names.push(s.to_string());
        self.out.push(HashMap::new());
        self.inn.push(HashMap::new());
        i
    }

    fn add_edge(&mut self, a: &str, b: &str, w: u64) {
        let a = self.node(a);
        let b = self.node(b);
        let e = self.out[a].entry(b).or_insert(w);
        if w < *e {
            *e = w;
        }
        let e = self.inn[b].entry(a).or_insert(w);
        if w < *e {
            *e = w;
        }
    }

    fn query(&self, a: &str, b: &str) -> String {
        let ai = match self.ids.get(a) {
            Some(&i) => i,
            None => return format!("unknown node {}", a),
        };
        let bi = match self.ids.get(b) {
            Some(&i) => i,
            None => return format!("unknown node {}", b),
        };
        if ai == bi {
            return format!("0 {}", a);
        }

        // Shortest distance from every node to `bi`, via Dijkstra on reversed edges.
        let n = self.names.len();
        let mut dist = vec![u64::MAX; n];
        let mut heap = BinaryHeap::new();
        dist[bi] = 0;
        heap.push(Reverse((0u64, bi)));
        while let Some(Reverse((d, x))) = heap.pop() {
            if d > dist[x] {
                continue;
            }
            for (&u, &w) in &self.inn[x] {
                let nd = d + w;
                if nd < dist[u] {
                    dist[u] = nd;
                    heap.push(Reverse((nd, u)));
                }
            }
        }

        if dist[ai] == u64::MAX {
            return "unreachable".to_string();
        }

        // Walk greedily along tight edges, always taking the smallest name.
        // Weights are >= 1, so every step strictly lowers the remaining cost and the walk ends at `bi`.
        let mut path = vec![ai];
        let mut cur = ai;
        while cur != bi {
            let next = self.out[cur]
                .iter()
                .filter(|(&v, &w)| dist[v] != u64::MAX && w + dist[v] == dist[cur])
                .map(|(&v, _)| v)
                .min_by(|x, y| self.names[*x].as_bytes().cmp(self.names[*y].as_bytes()))
                .unwrap();
            path.push(next);
            cur = next;
        }

        let names: Vec<&str> = path.iter().map(|&i| self.names[i].as_str()).collect();
        format!("{} {}", dist[ai], names.join(">"))
    }
}

fn valid_name(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_')
}

fn parse_weight(s: &str) -> Option<u64> {
    if s.is_empty() || !s.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let w: u64 = s.parse().ok()?;
    if (1..=1_000_000).contains(&w) {
        Some(w)
    } else {
        None
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut g = Graph::default();
    let mut out = String::new();

    for raw in input.split('\n') {
        let line = raw.strip_suffix('\r').unwrap_or(raw);
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(' ').collect();
        let reply = match fields.as_slice() {
            ["edge", a, b, w] if valid_name(a) && valid_name(b) && parse_weight(w).is_some() => {
                g.add_edge(a, b, parse_weight(w).unwrap());
                None
            }
            ["path", a, b] => Some(g.query(a, b)),
            _ => Some(format!("bad command: {}", line)),
        };
        if let Some(r) = reply {
            out.push_str(&r);
            out.push('\n');
        }
    }

    io::stdout().write_all(out.as_bytes()).unwrap();
}
